queries:
WITH c AS (
  SELECT product_id, COUNT(*) AS cnt
  FROM Order_Items
  GROUP BY product_id
),
s AS (
  SELECT product_id, cnt, cnt * 1.0 / (SELECT COUNT(*) FROM Order_Items) AS share
  FROM c
),
a AS (
  SELECT AVG(share) AS avg_share FROM s
)
SELECT
  (SELECT SUM(cnt) FROM s) AS sum_of_counts,
  (SELECT avg_share FROM a) AS average_share,
  (SELECT AVG(share - (SELECT avg_share FROM a)) FROM s WHERE share > (SELECT avg_share FROM a)) AS average_excess_over_average_share
SELECT AVG(cnt) FROM (SELECT p.product_id, COUNT(oi.order_item_id) AS cnt FROM Products p LEFT JOIN Order_Items oi ON p.product_id = oi.product_id GROUP BY p.product_id);
SELECT SUM(CAST(product_quantity AS INTEGER)) FROM Order_Items;
SELECT product_id, COUNT(DISTINCT order_id) FROM Order_Items GROUP BY product_id
SELECT COUNT(*) FROM Order_Items WHERE product_id IN (SELECT product_id FROM Products WHERE unit_price > (SELECT AVG(unit_price) FROM Products));
